int megasas_alloc_cmds(struct megasas_instance *instance) {
    struct megasas_cmd **cmds;
    int i, rc;

    cmds = kzalloc(instance->max_num_cmd * sizeof(*cmds), GFP_KERNEL);
    if (!cmds) {
        dev_err(&instance->pdev->dev, "Failed to allocate command array\n");
        return -ENOMEM;
    }

    for (i = 0; i < instance->max_num_cmd; i++) {
        cmds[i] = kzalloc(sizeof(struct megasas_cmd), GFP_KERNEL);
        if (!cmds[i]) {
            dev_err(&instance->pdev->dev, "Failed to allocate command structure %d\n", i);
            while (i--) {
                kfree(cmds[i]);
            }
            kfree(cmds);
            return -ENOMEM;
        }

        cmds[i]->index = i;
        cmds[i]->instance = instance;
        INIT_LIST_HEAD(&cmds[i].list);
        list_add_tail(&cmds[i].list, &instance->cmd_pool);
    }

    rc = megasas_create_frame_pool(instance);
    if (rc) {
        dev_err(&instance->pdev->dev, "Failed to create frame pool\n");
        for (i = 0; i < instance->max_num_cmd; i++) {
            kfree(cmds[i]);
        }
        kfree(cmds);
    }

    return rc;
}

int megasas_alloc_cmds(struct megasas_instance *instance) {
    struct megasas_cmd **cmds;
    int i, max_cmds = instance->max_cmds;
    int rc = 0;

    cmds = kmalloc(max_cmds * sizeof(struct megasas_cmd *), GFP_KERNEL);
    if (!cmds) {
        dev_err(&instance->pdev->dev, "Failed to allocate command pointers\n");
        return -ENOMEM;
    }

    for (i = 0; i < max_cmds; i++) {
        cmds[i] = kzalloc(sizeof(struct megasas_cmd), GFP_KERNEL);
        if (!cmds[i]) {
            while (i > 0) {
                kfree(cmds[--i]);
            }
            kfree(cmds);
            dev_err(&instance->pdev->dev, "Failed to allocate command structure\n");
            return -ENOMEM;
        }
        cmds[i]->index = i;
        cmds[i]->instance = instance;
        INIT_LIST_HEAD(&cmds[i]->list);
        list_add_tail(&cmds[i]->list, &instance->cmd_pool);
    }

    rc = megasas_create_frame_pool(instance, cmds);
    if (rc != 0) {
        for (i = 0; i < max_cmds; i++) {
            kfree(cmds[i]);
        }
        kfree(cmds);
    }

    return rc;
}

int megasas_alloc_cmds(struct megasas_instance *instance) {
    int i;
    struct megasas_cmd **cmds;
    int max_num_cmd = instance->max_num_cmd;

    cmds = kzalloc(max_num_cmd * sizeof(struct megasas_cmd *), GFP_KERNEL);
    if (!cmds) {
        dev_err(&instance->pdev->dev, "Failed to allocate command pointers\n");
        return -ENOMEM;
    }

    for (i = 0; i < max_num_cmd; i++) {
        struct megasas_cmd *cmd;

        cmd = kzalloc(sizeof(struct megasas_cmd), GFP_KERNEL);
        if (!cmd) {
            dev_err(&instance->pdev->dev, "Failed to allocate command\n");
            while (i--)
                kfree(cmds[i]);
            kfree(cmds);
            return -ENOMEM;
        }

        cmd->index = i;
        cmd->instance = instance;
        cmds[i] = cmd;
        INIT_LIST_HEAD(&cmd->list);
        list_add_tail(&cmd->list, &instance->cmd_pool);
    }

    if (megasas_create_frame_pool(instance) != 0) {
        while (!list_empty(&instance->cmd_pool)) {
            struct megasas_cmd *cmd = list_entry(instance->cmd_pool.next, struct megasas_cmd, list);
            list_del(&cmd->list);
            kfree(cmd);
        }
        kfree(cmds);
        return -ENOMEM;
    }

    return 0;
}

int megasas_alloc_cmds(struct megasas_instance *instance) {
    int i;
    struct megasas_cmd **cmd_list;
    struct list_head *cmd_pool = &instance->cmd_pool;
    struct megasas_cmd *cmd;

    cmd_list = kmalloc_array(instance->max_num_cmd, sizeof(struct megasas_cmd *), GFP_KERNEL);
    if (!cmd_list) {
        dev_err(&instance->pdev->dev, "Failed to allocate command list\n");
        return -ENOMEM;
    }

    instance->cmd_list = cmd_list;

    for (i = 0; i < instance->max_num_cmd; i++) {
        cmd = &instance->cmd_priv[i];
        cmd->instance = instance;
        cmd->index = i;
        INIT_LIST_HEAD(&cmd->list);
        list_add_tail(&cmd->list, cmd_pool);
    }

    if (megasas_create_frame_pool(instance)) {
        dev_err(&instance->pdev->dev, "Failed to create frame pool\n");
        kfree(cmd_list);
        return -ENOMEM;
    }

    return 0;
}

